globalThis.__PAGES = {"/admin.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<title>SURVIVOR SCREEN Admin</title>\n<style>\n:root{--bg:#070504;--c:#14100D;--c2:#1E1712;--l:#3A2A1C;--g:#FFC21A;--p:#E51B35;--t:#F7F2EA;--m:#A89C8C;--r:#FF5C7A;--y:#FFC107}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nbody{margin:0;background:var(--bg);color:var(--t);font:15px/1.4 system-ui,-apple-system,Segoe UI,sans-serif}\nheader{position:sticky;top:0;z-index:20;display:flex;align-items:center;gap:12px;background:#000;padding:12px 14px;border-bottom:1px solid var(--l)}\nheader b{letter-spacing:3px;flex:1}header button{width:auto;margin:0;padding:8px 12px}\n#drawer{position:fixed;inset:0 auto 0 0;width:260px;background:var(--c);border-right:1px solid var(--l);transform:translateX(-100%);transition:transform .25s;z-index:30;overflow:auto;padding:10px 0}\n#drawer.open{transform:none}#shade{position:fixed;inset:0;background:#0009;opacity:0;pointer-events:none;transition:.25s;z-index:25}#shade.open{opacity:1;pointer-events:auto}\n#drawer a{display:block;padding:13px 20px;color:var(--t);text-decoration:none;border-left:3px solid transparent}\n#drawer a.on{background:var(--c2);border-color:var(--g);color:var(--g)}\n#drawer h6{margin:14px 20px 4px;color:var(--m);font-size:11px;letter-spacing:1px;text-transform:uppercase}\nmain{padding:14px;max-width:900px;margin:auto;padding-bottom:80px}\nh2{margin:6px 0 14px;font-size:20px}\n.card{background:var(--c);border:1px solid var(--l);border-radius:16px;padding:14px;margin-bottom:12px}\n.row{display:flex;align-items:center;gap:12px}.grow{flex:1;min-width:0}\n.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}\n.stat b{display:block;font-size:22px}.stat span{color:var(--m);font-size:12px}\n.sub{color:var(--m);font-size:12px}.ell{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\nimg.th{width:54px;height:54px;border-radius:12px;object-fit:cover;background:var(--c2)}\nbutton{font:inherit;border:0;border-radius:12px;padding:12px 16px;background:var(--g);color:#000;font-weight:700;width:100%;margin-top:10px;transition:transform .12s}\nbutton:active{transform:scale(.95)}button.s{width:auto;margin:0;padding:8px 12px;font-size:13px}\nbutton.p{background:var(--p);color:#fff}button.d{background:var(--r);color:#fff}button.o{background:var(--c2);color:var(--t);border:1px solid var(--l)}\nbutton:disabled{opacity:.4}\nlabel{display:block;color:var(--m);font-size:12px;margin:12px 0 5px}\ninput,select,textarea{width:100%;padding:12px;border-radius:12px;border:1px solid var(--l);background:#0F0F1C;color:var(--t);font:inherit}\ntextarea{min-height:90px;resize:vertical}input[type=checkbox]{width:auto;transform:scale(1.4);margin-right:8px}\n.chip{display:inline-block;padding:3px 9px;border-radius:99px;font-size:11px;font-weight:700;background:var(--c2);color:var(--m)}\n.ok{background:#0F5C47;color:var(--g)}.bad{background:#5C1A2A;color:var(--r)}.warn{background:#4A3A10;color:var(--y)}\n.tabs{display:flex;gap:6px;overflow:auto;margin-bottom:12px}.tabs button{width:auto;margin:0;padding:8px 14px;background:var(--c2);color:var(--m);font-size:13px}.tabs button.on{background:var(--g);color:#000}\n#modal{position:fixed;inset:0;background:#000a;display:none;align-items:flex-end;justify-content:center;z-index:50}\n#modal.open{display:flex}#sheet{background:var(--c);width:100%;max-width:640px;max-height:92vh;overflow:auto;border-radius:22px 22px 0 0;padding:18px;animation:up .25s}\n@keyframes up{from{transform:translateY(60px);opacity:0}}\n#toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%) translateY(80px);background:#000;border:1px solid var(--l);padding:12px 18px;border-radius:14px;z-index:99;transition:.3s;max-width:90vw}\n#toast.show{transform:translateX(-50%)}#toast.err{border-color:var(--r);color:var(--r)}\n.spin{width:34px;height:34px;border-radius:50%;border:4px solid var(--l);border-top-color:var(--g);animation:r .8s linear infinite;margin:40px auto}@keyframes r{to{transform:rotate(360deg)}}\nimg.pv{width:100%;max-height:170px;object-fit:cover;border-radius:12px;margin-top:8px}\n</style></head><body>\n\n<div id=\"loginView\" style=\"max-width:420px;margin:12vh auto;padding:16px\">\n  <div style=\"text-align:center\"><img src=\"/logo.png\" alt=\"SURVIVOR SCREEN\" style=\"width:120px;height:120px;border-radius:24px\"></div><h2 style=\"letter-spacing:4px;text-align:center\">SURVIVOR SCREEN ADMIN</h2>\n  <div class=\"card\" id=\"loginCard\"><label>Admin username</label><input id=\"u\" autocapitalize=\"none\"><label>Password</label><input id=\"p\" type=\"password\">\n  <button id=\"bl\">LOGIN</button><button class=\"s o\" id=\"forgotBtn\" type=\"button\">Customer Support</button><div id=\"lm\" class=\"sub\" style=\"color:var(--r);margin-top:10px\"></div></div>\n  <div class=\"card\" id=\"forgotCard\" style=\"display:none\"><h3>Customer Support</h3><div class=\"sub\">For password help, open the configured customer-support link.</div><button id=\"openSupport\">OPEN CUSTOMER SUPPORT</button><div id=\"fgMsg\" class=\"sub\" style=\"margin-top:10px\"></div><button class=\"s o\" id=\"backLogin\" type=\"button\">Back to Login</button></div>\n</div>\n\n<div id=\"app\" style=\"display:none\">\n  <header><button class=\"s o\" onclick=\"nav(1)\">☰</button><b id=\"ttl\">DASHBOARD</b><button class=\"s o\" onclick=\"logout()\">Logout</button></header>\n  <div id=\"shade\" onclick=\"nav(0)\"></div>\n  <nav id=\"drawer\"></nav>\n  <main id=\"main\"></main>\n</div>\n<div id=\"modal\"><div id=\"sheet\"></div></div><div id=\"toast\"></div>\n\n<script src=\"https://www.gstatic.com/firebasejs/10.12.2/firebase-app-compat.js\"></script>\n<script src=\"https://www.gstatic.com/firebasejs/10.12.2/firebase-auth-compat.js\"></script>\n<script>\nconst DB='__FB_DB__';\nfirebase.initializeApp({apiKey:'__FB_API__',authDomain:'__FB_AUTH__',projectId:'__FB_PROJECT__'});\nconst $=id=>document.getElementById(id);let user=null,adminInfo={role:'',gameIds:[]};\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst money=n=>'₹'+(Math.round((+n||0)*100)/100);\nconst fdate=ms=>ms?new Date(ms).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):'-';\nfunction toast(m,e){const t=$('toast');t.textContent=m;t.className='show'+(e?' err':'');clearTimeout(toast.t);toast.t=setTimeout(()=>t.className='',2800)}\nasync function api(method,path,body){\n  const tok=await user.getIdToken();\n  const r=await fetch('/api'+path,{method,headers:{Authorization:'Bearer '+tok,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});\n  const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||('Error '+r.status));return j}\nasync function read(path){return(await(await fetch(DB+'/'+path+'.json')).json())||{}}\nconst rows=o=>Object.entries(o).map(([id,v])=>({id,...v}));\nconst load=()=>$('main').innerHTML='<div class=\"spin\"></div>';\n\n/* ---------- login ---------- */\n$('forgotBtn').onclick=()=>{ $('loginCard').style.display='none'; $('forgotCard').style.display='block'; $('fgMsg').textContent=''; };\n$('backLogin').onclick=()=>{ $('forgotCard').style.display='none'; $('loginCard').style.display='block'; };\n$('openSupport').onclick=async()=>{ try { const c=await read('appConfig'); const url=String(c.supportUrl||c.telegramUrl||c.whatsappUrl||'').trim(); if(!url) throw Error('Customer support link is not configured'); window.location.href=url; } catch(e) { $('fgMsg').textContent=e.message||'Could not open Customer Support'; } };\n$('bl').onclick=async()=>{$('lm').textContent='';\n  try{const c=await firebase.auth().signInWithEmailAndPassword($('u').value.trim().toLowerCase()+'@arenax.user',$('p').value);user=c.user;\n    Object.assign(adminInfo,await api('GET','/admin/me'));$('loginView').style.display='none';$('app').style.display='block';buildNav();go('dash')\n  }catch(e){$('lm').textContent=/Admins only/.test(e.message)?'This account is not an admin':'Wrong username or password'}};\nfunction logout(){firebase.auth().signOut();location.reload()}\n\n/* ---------- navigation ---------- */\nconst NAV=[['Overview',[['dash','Dashboard']]],['Content',[['games','Games'],['matches','Matches'],['ads','Home Ads'],['banners','More Banners'],['announcements','Announcements'],['feedback','Feedback'],['tutorials','Tutorials']]],\n['Money',[['withdrawals','Withdrawals'],['deposits','Deposits']]],['People',[['users','Users'],['admins','Admins']]],['System',[['settings','App Settings'],['logs','Activity Log']]]];\nlet cur='dash';\nfunction buildNav(){const items=adminInfo.role==='owner'?NAV:[['Match Operations',[['dash','Dashboard'],['matches','Assigned Matches']]]];$('drawer').innerHTML=items.map(([h,l])=>'<h6>'+h+'</h6>'+l.map(([k,n])=>`<a href=\"#\" data-k=\"${k}\" onclick=\"go('${k}');return false\">${n}</a>`).join('')).join('')}\nfunction nav(o){$('drawer').classList.toggle('open',!!o);$('shade').classList.toggle('open',!!o)}\nfunction go(k){if(adminInfo.role!=='owner'&&!['dash','matches'].includes(k)){toast('Staff can only manage assigned game matches',1);return}cur=k;nav(0);document.querySelectorAll('#drawer a').forEach(a=>a.classList.toggle('on',a.dataset.k===k));\n  const n=NAV.flatMap(x=>x[1]).find(x=>x[0]===k);$('ttl').textContent=(n?n[1]:k).toUpperCase();load();\n  (PAGES[k]||(()=>collPage(k)))().catch(e=>{$('main').innerHTML='<div class=\"card\" style=\"color:var(--r)\">'+esc(e.message)+'</div>'})}\nfunction modal(html){$('sheet').innerHTML=html;$('modal').classList.add('open')}\nfunction close_(){$('modal').classList.remove('open')}\n$('modal').onclick=e=>{if(e.target.id==='modal')close_()};\n\n/* ---------- image helpers ---------- */\nfunction shrink(f){return new Promise(r=>{if(f.size<1.2e6)return r(f);const i=new Image();i.onload=()=>{const s=Math.min(1,1600/Math.max(i.width,i.height));const c=document.createElement('canvas');c.width=i.width*s;c.height=i.height*s;c.getContext('2d').drawImage(i,0,0,c.width,c.height);c.toBlob(b=>r(b),'image/jpeg',.85)};i.src=URL.createObjectURL(f)})}\nasync function uploadImage(file){const b=await shrink(file),tok=await user.getIdToken();\n  const r=await fetch('/api/admin/upload',{method:'PUT',headers:{Authorization:'Bearer '+tok,'Content-Type':b.type||file.type},body:b});\n  const j=await r.json();if(!r.ok)throw new Error(j.error||'Upload failed');return j.url}\n\n/* ---------- generic collection pages ---------- */\nconst MODES={Solo:1,Duo:2,Squad:4};\nconst SCHEMA={\n games:{one:'Game',fields:[{k:'name',l:'Name',req:1},{k:'image',l:'Tile image',t:'image'},{k:'order',l:'Order (1 = first)',t:'number'},{k:'featured',l:'Show on Home under TOP GAMES',t:'bool'},{k:'active',l:'Visible in app',t:'bool',def:true}],\n   title:r=>r.name,sub:r=>(r.featured?'★ On Home · ':'')+(r.active===false?'Hidden':'Visible')+' · order '+(r.order??'-'),thumb:'image'},\n  topgames:{one:'Top Game',fields:[{k:'name',l:'Name',req:1},{k:'image',l:'Tile image',t:'image'},{k:'order',l:'Order (1 = first)',t:'number'},{k:'featured',l:'Show on Home',t:'bool',def:true},{k:'active',l:'Visible in app',t:'bool',def:true}],\n   title:r=>r.name,sub:r=>(r.featured?'★ On Home · ':'')+(r.active===false?'Hidden':'Visible')+' · order '+(r.order??'-'),thumb:'image'},\n earn_banners:{one:'Earn Banner',fields:[{k:'title',l:'Title (shown on banner)'},{k:'subtitle',l:'Subtitle'},{k:'image',l:'Banner image',t:'image'},{k:'action',l:'Link when tapped (https://… or refer, addcoins, wallet)'},{k:'order',l:'Order',t:'number'},{k:'active',l:'Active',t:'bool',def:true}],\n   title:r=>r.title||'Banner',sub:r=>(r.active===false?'Hidden':'Live')+' · '+(r.action||'no link'),thumb:'image'},\n ads:{one:'Ad banner',fields:[{k:'title',l:'Title (only for you)'},{k:'image',l:'Banner image',t:'image'},{k:'action',l:'Link when tapped (https://… or refer, spin, addcoins, wallet, leaders, support, announcements)'},{k:'order',l:'Order',t:'number'}],\n   title:r=>r.title||'Ad',sub:r=>r.action||'no link',thumb:'image'},\n banners:{one:'Banner',fields:[{k:'title',l:'Title (only for you)'},{k:'image',l:'Banner image',t:'image'},{k:'action',l:'Link when tapped (https://… or refer, spin, …)'},{k:'order',l:'Order',t:'number'}],\n   title:r=>r.title||'Banner',sub:r=>r.action||'no link',thumb:'image'},\n announcements:{one:'Announcement',fields:[{k:'text',l:'Text',t:'area',req:1},{k:'link',l:'Link (optional)'},{k:'order',l:'Order',t:'number'},{k:'active',l:'Active',t:'bool',def:true}],\n   title:r=>r.text,sub:r=>(r.active===false?'Hidden':'Live')+(r.link?' · has link':'')},\n feedback:{one:'Feedback',fields:[{k:'username',l:'Username',req:1},{k:'text',l:'Feedback text',t:'area',req:1},{k:'stars',l:'Stars (1-5)',t:'number',def:5}],title:r=>r.username,sub:r=>'★'.repeat(r.stars||5)+' '+(r.text||'')},\n tutorials:{one:'Tutorial video',fields:[{k:'title',l:'Title',req:1},{k:'url',l:'YouTube / video link',req:1},{k:'order',l:'Order',t:'number'}],title:r=>r.title,sub:r=>r.url},\n matches:{one:'Match',fields:[{k:'gameId',l:'Game',t:'game',req:1},{k:'title',l:'Match title',req:1},{k:'mode',l:'Mode',t:'mode'},{k:'maxPlayers',l:'Max players (slots)',t:'number',def:48},{k:'entryFee',l:'Entry fee',t:'number',def:0},{k:'prizePool',l:'Prize pool',t:'number'},{k:'perKill',l:'Per kill',t:'number',def:0},{k:'prizeBreakup',l:'Prize breakup shown in dropdown (e.g. 1st ₹200 / 2nd ₹100)',t:'area'},{k:'startTime',l:'Start date & time',t:'dt',req:1},{k:'status',l:'Status',t:'status'},{k:'map',l:'Map / tag line'},{k:'banner',l:'Banner image',t:'image'},{k:'rules',l:'Rules / description',t:'area'}],\n   title:r=>r.title,sub:r=>`${r.status} · ${fdate(r.startTime)} · ${Object.keys(r.joined||{}).length}/${r.maxPlayers} joined · fee ${r.entryFee}`,thumb:'banner',\n   actions:r=>`<button class=\"s o\" onclick=\"roomModal('${r.id}')\">Room</button><button class=\"s o\" onclick=\"playersModal('${r.id}')\">Players</button>`+(r.status!=='completed'&&r.status!=='cancelled'?`<button class=\"s p\" onclick=\"resultModal('${r.id}')\">Result</button><button class=\"s d\" onclick=\"cancelMatch('${r.id}')\">Cancel &amp; refund</button>`:'')+(adminInfo.role==='owner'?`<button class=\"s d\" onclick=\"deleteTournament('${r.id}')\">Delete</button>`:'')}\n};\nlet cache={};\nasync function collPage(k){\n  const S=SCHEMA[k];let data=rows(await read(k));if(k==='matches'&&adminInfo.role!=='owner')data=data.filter(m=>(adminInfo.gameIds||[]).includes(String(m.gameId||'')));cache[k]=data;\n  if(k==='games')data.sort((a,b)=>(a.order||99)-(b.order||99));\n  if(k==='matches'){const f=window.mFilter||'upcoming';data.sort((a,b)=>(b.startTime||0)-(a.startTime||0));\n    var shown=data.filter(m=>m.status===f);\n    var tabs='<div class=\"tabs\">'+['upcoming','ongoing','completed','cancelled'].map(s=>`<button class=\"${f===s?'on':''}\" onclick=\"window.mFilter='${s}';go('matches')\">${s}</button>`).join('')+'</div>'}\n  const list=(shown||data);\n  $('main').innerHTML=`<div class=\"row\"><h2 class=\"grow\">${$('ttl').textContent[0]+$('ttl').textContent.slice(1).toLowerCase()}</h2>${k==='games'?'':`<button class=\"s\" onclick=\"edit('${k}')\">+ New</button>`}</div>${tabs||''}`+\n   (list.length?list.map(r=>`<div class=\"card\"><div class=\"row\">${S.thumb&&r[S.thumb]?`<img class=\"th\" src=\"${esc(r[S.thumb])}\">`:''}<div class=\"grow\"><div class=\"ell\"><b>${esc(S.title(r))}</b></div><div class=\"sub ell\">${esc(S.sub(r))}</div></div><button class=\"s o\" onclick=\"edit('${k}','${r.id}')\">Edit</button></div>${S.actions?`<div class=\"row\" style=\"margin-top:10px;flex-wrap:wrap\">${S.actions(r)}</div>`:''}</div>`).join(''):'<div class=\"card sub\">Nothing here yet. Tap “+ New”.</div>')}\n\nfunction toLocal(ms){return ms?new Date(ms-new Date().getTimezoneOffset()*6e4).toISOString().slice(0,16):''}\nasync function edit(k,id){\n  if(adminInfo.role!=='owner'&&k!=='matches')return toast('Staff can only manage assigned game matches',1);const S=SCHEMA[k];const r=id?cache[k].find(x=>x.id===id):{};let games=(k==='matches')?rows(await read('games')):[];if(k==='matches'&&adminInfo.role!=='owner')games=games.filter(g=>(adminInfo.gameIds||[]).includes(g.id));\n  const f=S.fields.map(x=>{const v=r[x.k]??x.def??'';let inp;\n    if(x.t==='bool')return`<label style=\"display:flex;align-items:center;color:var(--t);font-size:15px\"><input type=\"checkbox\" data-k=\"${x.k}\" ${(r[x.k]??x.def)?'checked':''}>${x.l}</label>`;\n    if(x.t==='area')inp=`<textarea data-k=\"${x.k}\">${esc(v)}</textarea>`;\n    else if(x.t==='image')inp=`<input data-k=\"${x.k}\" value=\"${esc(v)}\" placeholder=\"Image link (or choose a file below)\"><input type=\"file\" accept=\"image/*\" onchange=\"pickImg(this)\" style=\"margin-top:8px\"><div class=\"sub image-meta\">${v?'Loading exact size…':'Select an image to show exact size'}</div>${v?`<img class=\"pv\" src=\"${esc(v)}\" onload=\"remoteImageInfo(this.src,this.previousElementSibling)\">`:''}`;\n    else if(x.t==='dt')inp=`<input type=\"datetime-local\" data-k=\"${x.k}\" data-t=\"dt\" value=\"${toLocal(v)}\">`;\n    else if(x.t==='game')inp=`<select data-k=\"${x.k}\">${games.map(g=>`<option value=\"${g.id}\" ${g.id===v?'selected':''}>${esc(g.name)}</option>`).join('')}</select>`;\n    else if(x.t==='mode')inp=`<select data-k=\"${x.k}\">${Object.keys(MODES).map(m=>`<option ${m===(v||'Solo')?'selected':''}>${m}</option>`).join('')}</select>`;\n    else if(x.t==='status')inp=`<select data-k=\"${x.k}\">${['upcoming','ongoing','completed'].map(m=>`<option ${m===(v||'upcoming')?'selected':''}>${m}</option>`).join('')}</select>`;\n    else inp=`<input data-k=\"${x.k}\" data-t=\"${x.t||'text'}\" type=\"${x.t==='number'?'number':'text'}\" step=\"any\" value=\"${esc(v)}\">`;\n    return`<label>${x.l}${x.req?' *':''}</label>${inp}`}).join('');\n  modal(`<h2>${id?'Edit':'New'} ${S.one}</h2>${f}<button onclick=\"save('${k}','${id||''}')\">SAVE</button>${id&&adminInfo.role==='owner'?`<button class=\"d\" onclick=\"del('${k}','${id}')\">DELETE</button>`:''}<button class=\"o\" onclick=\"close_()\">Cancel</button>`)}\nasync function formatBytes(n){if(!n)return '0 B';const units=['B','KB','MB','GB'],i=Math.min(Math.floor(Math.log(n)/Math.log(1024)),units.length-1);return (n/Math.pow(1024,i)).toFixed(i?2:0)+' '+units[i]}\nfunction imageInfo(file,meta){if(!file||!meta)return;const img=new Image();img.onload=()=>{meta.textContent=`Exact size: ${img.naturalWidth} × ${img.naturalHeight} px · File size: ${formatBytes(file.size)}`};img.src=URL.createObjectURL(file)}\nfunction remoteImageInfo(url,meta){if(!url||!meta)return;const img=new Image();img.onload=()=>{meta.textContent=`Exact size: ${img.naturalWidth} × ${img.naturalHeight} px`};img.onerror=()=>{meta.textContent='Exact size: unable to read remote image'};img.src=url}\nasync function pickImg(el){const f=el.files[0];if(!f)return;const input=el.previousElementSibling,meta=el.nextElementSibling;imageInfo(f,meta);toast('Uploading image…');try{const u=await uploadImage(f);input.value=u;let pv=meta.nextElementSibling;if(!pv){pv=document.createElement('img');pv.className='pv';meta.after(pv)}pv.src=u;toast('Image saved to Telegram channel')}catch(e){toast(e.message,1)}}\nasync function pickCfgImg(el,key){const f=el.files[0];if(!f)return;const input=document.querySelector('[data-c=\"'+key+'\"]'),meta=el.nextElementSibling;imageInfo(f,meta);toast('Uploading image…');try{const u=await uploadImage(f);if(input)input.value=u;toast('Image uploaded; save settings to apply')}catch(e){toast(e.message,1)}}\nasync function loadUserStats(){try{const s=await api('GET','/admin/stats');$('userStats').innerHTML=`<div class=\"grid\"><div class=\"stat\"><b>${s.userCount||0}</b><span>Total users</span></div><div class=\"stat\"><b>${s.blocked||0}</b><span>Blocked users</span></div></div>`}catch(e){$('userStats').innerHTML='<div class=\"sub\">User total unavailable: '+esc(e.message)+'</div>'}}\nfunction deleteTournament(id){if(!confirm('Delete this tournament permanently? Joined players, room details and result data will not be recoverable.'))return;api('DELETE','/admin/content/matches/'+id).then(()=>{toast('Tournament deleted');go('matches')}).catch(e=>toast(e.message,1))}\nasync function save(k,id){const S=SCHEMA[k];const b={};\n  for(const x of S.fields){const el=document.querySelector(`#sheet [data-k=\"${x.k}\"]`);if(!el)continue;\n    let v=el.type==='checkbox'?el.checked:el.value;\n    if(x.t==='dt')v=v?new Date(v).getTime():'';\n    if(x.req&&(v===''||v==null)){return toast(x.l+' is required',1)}\n    if(v!=='')b[x.k]=v;else if(x.t!=='number'&&x.t!=='dt')b[x.k]=''}\n  if(k==='matches')b.playersPerTeam=MODES[b.mode]||1;\n  try{await api('PUT','/admin/content/'+k+(id?'/'+id:''),b);toast('Saved');close_();go(k)}catch(e){toast(e.message,1)}}\nasync function del(k,id){if(!confirm('Delete this permanently?'))return;try{await api('DELETE','/admin/content/'+k+'/'+id);toast('Deleted');close_();go(k)}catch(e){toast(e.message,1)}}\nasync function cancelMatch(id){if(!confirm('Cancel this match and refund every player\\'s entry fee?'))return;try{const r=await api('POST','/admin/match/'+id+'/cancel');const list=(r.refundReport||[]).map(x=>`${x.username} (${x.ign||'-'}): ${money(x.amount)}`).join('\\n');alert(list?`Refunded ${r.refunded} player(s):\\n\\n${list}`:'No paid entry fees needed refunding.');go('matches')}catch(e){toast(e.message,1)}}\n\n/* ---------- match tools ---------- */\nasync function roomModal(id){const m=await api('GET','/admin/match/'+id);\n  modal(`<h2>Room details</h2><div class=\"sub\">Only players who joined can see this.</div><label>Room ID</label><input id=\"rid\" value=\"${esc(m.room.roomId||'')}\"><label>Password</label><input id=\"rpw\" value=\"${esc(m.room.roomPass||'')}\"><button onclick=\"saveRoom('${id}')\">SAVE</button><button class=\"o\" onclick=\"close_()\">Close</button>`)}\nasync function saveRoom(id){try{await api('PUT','/admin/match/'+id+'/room',{roomId:$('rid').value,roomPass:$('rpw').value});toast('Room saved');close_()}catch(e){toast(e.message,1)}}\nasync function playersModal(id){const m=await api('GET','/admin/match/'+id);const j=Object.values(m.joined||{}).sort((a,b)=>a.team-b.team||a.pos-b.pos);\n  modal(`<h2>Players (${j.length}/${m.maxPlayers})</h2>`+(j.map((p,i)=>`<div class=\"row\" style=\"padding:8px 0;border-bottom:1px solid var(--l)\"><span class=\"sub\" style=\"width:28px\">${i+1}</span><span class=\"grow\">${esc(p.ign)}${p.gameUid?' · UID '+esc(p.gameUid):''}</span><span class=\"sub\">T${p.team}-${String.fromCharCode(64+p.pos)}</span></div>`).join('')||'<div class=\"sub\">No one joined yet.</div>')+'<button class=\"o\" onclick=\"close_()\">Close</button>')}\nasync function resultModal(id){const m=await api('GET','/admin/match/'+id);const j=Object.values(m.joined||{}).sort((a,b)=>a.team-b.team||a.pos-b.pos);\n  if(!j.length)return toast('Nobody joined this match',1);window._rm=m;\n  modal(`<h2>Publish result</h2><div class=\"sub\">Prize pool ${money(m.prizePool)} · per kill ${money(m.perKill)}. Players you leave empty get nothing. This pays winners once and cannot be undone.</div>`+\n   j.map((p,i)=>`<div class=\"card\" style=\"margin:10px 0\"><b>${esc(p.ign)}</b> <span class=\"sub\">${p.gameUid?'UID '+esc(p.gameUid)+' · ':''}T${p.team}-${String.fromCharCode(64+p.pos)}</span><div class=\"row\" style=\"margin-top:6px\"><div class=\"grow\"><label style=\"margin-top:0\">Kills</label><input type=\"number\" min=\"0\" data-r=\"${i}\" data-f=\"kills\"></div><div class=\"grow\"><label style=\"margin-top:0\">Rank prize ₹</label><input type=\"number\" min=\"0\" data-r=\"${i}\" data-f=\"prize\"></div></div><label style=\"display:flex;align-items:center;color:var(--t);font-size:14px\"><input type=\"checkbox\" data-r=\"${i}\" data-f=\"winner\">Winner (counts as a win)</label></div>`).join('')+\n   `<button onclick=\"submitResult('${id}')\">PAY & PUBLISH</button><button class=\"o\" onclick=\"close_()\">Cancel</button>`)}\nasync function submitResult(id){const m=window._rm;const j=Object.values(m.joined||{}).sort((a,b)=>a.team-b.team||a.pos-b.pos);const results=[];\n  j.forEach((p,i)=>{const g=f=>document.querySelector(`#sheet [data-r=\"${i}\"][data-f=\"${f}\"]`);const kills=+g('kills').value||0,prize=+g('prize').value||0,winner=g('winner').checked;results.push({uid:p.uid,kills,prize,winner})});\n  if(!results.some(r=>r.kills||r.prize||r.winner))return toast('Enter at least one result',1);\n  const tot=results.reduce((s,r)=>s+r.prize+r.kills*(m.perKill||0),0);if(!confirm('Pay '+money(tot)+' to '+results.length+' player(s) (everyone is listed in the result) and close this match?'))return;\n  try{await api('POST','/admin/match/'+id+'/result',{results});toast('Result published, winners paid');close_();go('matches')}catch(e){toast(e.message,1)}}\n\n/* ---------- special pages ---------- */\nconst PAGES={\n async topgames(){const note='<div class=\\'card warn\\' style=\\'margin-bottom:12px\\'><b>⚠ Top Games</b><div class=\\'sub\\'>Shown in the 2-col grid on Home. Featured+Active=ON to display.</div></div>';await collPage('topgames');$('main').innerHTML=note+$('main').innerHTML},\n async earn_banners(){const note='<div class=\\'card warn\\' style=\\'margin-bottom:12px\\'><b>⚠ Earn Banners</b><div class=\\'sub\\'>Banner cards in the Earn section. Add image + action + Active=ON.</div></div>';await collPage('earn_banners');$('main').innerHTML=note+$('main').innerHTML},\n async dash(){if(adminInfo.role!=='owner'){$('main').innerHTML=`<div class=\"card\"><h2>Staff Match Panel</h2><div class=\"sub\">You can manage only your assigned game categories.</div><button onclick=\"go('matches')\">OPEN ASSIGNED MATCHES</button></div>`;return}const s=await api('GET','/admin/stats');const w=await api('GET','/admin/withdrawals?status=pending');\n  $('main').innerHTML=`<div class=\"grid\">${[['Users',s.userCount],['Blocked',s.blocked],['Wallet total (owed to users)',money(s.walletTotal)],['Deposits today',money(s.todayDeposits)+' ('+s.todayCount+')'],['Pending withdrawals',s.pendingCount+' · '+money(s.pendingAmount)],['Live matches',s.live],['Upcoming matches',s.upcoming]].map(([a,b])=>`<div class=\"card stat\"><b>${b}</b><span>${a}</span></div>`).join('')}</div>\n  <h2>Pending withdrawals</h2>`+(w.length?w.slice(0,5).map(wCard).join(''):'<div class=\"card sub\">None 🎉</div>')+`<button class=\"o\" onclick=\"go('withdrawals')\">Open all withdrawals</button>`},\n async withdrawals(){const st=window.wSt||'pending';const w=await api('GET','/admin/withdrawals?status='+st);\n  $('main').innerHTML='<div class=\"tabs\">'+['pending','paid','rejected'].map(s=>`<button class=\"${st===s?'on':''}\" onclick=\"window.wSt='${s}';go('withdrawals')\">${s}</button>`).join('')+'</div>'+(w.length?w.map(wCard).join(''):'<div class=\"card sub\">Nothing here.</div>')},\n async deposits(){const st=window.dSt||'all';const d=await api('GET','/admin/deposits?status='+st);\n  $('main').innerHTML='<div class=\"tabs\">'+['all','manual_pending','success','pending','rejected','expired','amount_mismatch'].map(s=>`<button class=\"${st===s?'on':''}\" onclick=\"window.dSt='${s}';go('deposits')\">${s}</button>`).join('')+'</div>'+\n   (d.length?d.map(x=>`<div class=\"card\"><div class=\"row\"><div class=\"grow\"><b>${money(x.amount)}</b> <span class=\"chip ${x.status==='success'?'ok':(x.status==='pending'||x.status==='manual_pending')?'warn':'bad'}\">${x.status}</span><div class=\"sub\">${esc(x.gateway)} · ${fdate(x.createdAt)}${x.username?' · '+esc(x.username):''}</div>${x.utr?`<div class=\"sub\">UTR: <b style=\"color:var(--t)\">${esc(x.utr)}</b></div>`:''}<div class=\"sub ell\">${esc(x.id)}</div></div><button class=\"s o\" onclick=\"userModal('${x.uid}')\">User</button></div>${x.status==='manual_pending'?`<div class=\"row\" style=\"margin-top:10px\"><button class=\"s\" onclick=\"depAct('${x.id}','approve')\">✓ Approve & add coins</button><button class=\"s d\" onclick=\"depAct('${x.id}','reject')\">Reject</button></div>`:''}</div>`).join(''):'<div class=\"card sub\">No deposits.</div>')},\n async users(){$('main').innerHTML=`<div class=\"card\" id=\"userStats\"><div class=\"spin\"></div></div><div class=\"row\"><input id=\"uq\" placeholder=\"Search username…\" class=\"grow\"><button class=\"s\" onclick=\"usersList()\">Search</button></div><div id=\"ul\"></div>`;$('uq').onkeydown=e=>{if(e.key==='Enter')usersList()};loadUserStats();usersList()},\n async admins(){const a=await api('GET','/admin/admins');const games=rows(await read('games')).filter(g=>g.active!==false);\n  window._admins=a;window._adminGames=games;$('main').innerHTML=`<div class=\"card\"><label style=\"margin-top:0\">Add an existing user as Admin or Staff</label><input id=\"an\" autocapitalize=\"none\" placeholder=\"Username\"><label>Role</label><select id=\"ar\" onchange=\"roleChanged()\"><option value=\"staff\">Staff — assigned game matches only</option><option value=\"owner\">Admin — full permissions</option></select><div class=\"staff-assign\"><label>Assign active game categories (required for Staff)</label>${games.map(g=>`<label style=\"display:flex;align-items:center;color:var(--t)\"><input type=\"checkbox\" data-admin-game value=\"${esc(g.id)}\">${esc(g.name)}</label>`).join('')||'<div class=\"sub\">Add an active game before creating match Staff.</div>'}</div><button onclick=\"setAdmin(true)\">ADD ADMIN / STAFF</button></div>`+a.map(x=>{const assigned=(x.gameIds||[]).map(id=>games.find(g=>g.id===id)?.name||id).join(', ');return `<div class=\"card\"><div class=\"row\"><b class=\"grow\">${esc(x.username)}</b><span class=\"chip\">${esc(x.role)}</span></div><div class=\"sub\">${x.role==='staff'?'Assigned games: '+esc(assigned||'none'):'Full owner permissions'}</div><div class=\"row\" style=\"margin-top:10px\">${x.role==='staff'?`<button class=\"s p\" onclick=\"manageAdminGames('${esc(x.uid)}')\">Manage Games</button>`:`<button class=\"s o\" onclick=\"setRole('${esc(x.uid)}','staff')\">Make Staff</button>`}<button class=\"s d\" onclick=\"setAdmin(false,'${esc(x.username)}')\">Remove</button></div></div>`}).join('')},\n async logs(){const l=await api('GET','/admin/logs');$('main').innerHTML=l.map(x=>`<div class=\"card\"><b>${esc(x.action)}</b> <span class=\"sub\">${fdate(x.at)}</span><div class=\"sub ell\">${esc(x.target||'')} ${esc(JSON.stringify(x.data||{}))}</div></div>`).join('')||'<div class=\"card sub\">No activity yet.</div>'},\n async settings(){const c=await read('appConfig');\n  const F=[['homeBannerImage','Home Banner image',2],['homeBannerTitle','Home Banner title'],['homeBannerSubtitle','Home Banner subtitle',1],['homeAction1Image','Refer & Earn image',2],['homeAction2Image','Tutorial image',2],['homeAction3Image','Wallet image',2],['homeAction4Image','Leaders image',2],['homeAction5Image','Support image',2],['welcomeImage1','Welcome image 1',2],['welcomeTitle1','Welcome title 1'],['welcomeSubtitle1','Welcome subtitle 1',1],['welcomeImage2','Welcome image 2',2],['welcomeTitle2','Welcome title 2'],['welcomeSubtitle2','Welcome subtitle 2',1],['welcomeImage3','Welcome image 3',2],['welcomeTitle3','Welcome title 3'],['welcomeSubtitle3','Welcome subtitle 3',1],['payment1Name','Payment method 1 name'],['payment1Id','Payment method 1 gateway ID'],['payment1Active','Payment method 1 active (1/blank)'],['payment2Name','Payment method 2 name'],['payment2Id','Payment method 2 gateway ID'],['payment2Active','Payment method 2 active (1/blank)'],['manualPayActive','Manual payment active (1 = on, blank = off)'],['manualPayName','Manual payment: account holder name'],['manualPayUpi','Manual payment: your UPI ID'],['manualPayQr','Manual payment: QR image',2],['manualPayNote','Manual payment: instructions for players',1],['tutorialUrl','App tutorial fallback link'],['supportUrl','Customer support link (Telegram / WhatsApp)'],['telegramUrl','Telegram community link'],['whatsappUrl','WhatsApp channel link'],['instagramUrl','Instagram link'],['youtubeUrl','YouTube link'],['shareText','Share-app message'],['referText','Refer & Earn text (English)',1],['referTextHi','Refer & Earn text (Hindi)',1],['aboutText','About us text',1],['termsText','Terms & Conditions text',1],['minWithdraw','Minimum withdrawal (₹)'],['minDeposit','Minimum deposit (₹)'],['maxDeposit','Maximum deposit (₹)'],['referralBonus','Referral bonus (₹)'],['maintenance','Maintenance mode (1 = on, blank = off)'],['maintenanceText','Maintenance message',1]];\n  $('main').innerHTML='<div class=\"card\"><h2>App Settings</h2>'+F.map(([k,l,a])=>`<label>${l}</label>`+(a===1?`<textarea data-c=\"${k}\">${esc(c[k]||'')}</textarea>`:a===2?`<input data-c=\"${k}\" value=\"${esc(c[k]||'')}\" placeholder=\"Image URL\"><input type=\"file\" accept=\"image/*\" onchange=\"pickCfgImg(this,'${k}')\" style=\"margin-top:8px\"><div class=\"sub image-meta\">${c[k]?'Loading exact size…':'Select an image to show exact size'}</div>${c[k]?`<img class=\"pv\" src=\"${esc(c[k])}\" onload=\"remoteImageInfo(this.src,this.previousElementSibling)\">`:''}`:`<input data-c=\"${k}\" value=\"${esc(c[k]||'')}\">`)).join('')+'<button onclick=\"saveCfg()\">SAVE SETTINGS</button></div><div class=\"card\" id=\"zapCard\"><h2>ZapUPI Payment Key</h2><div class=\"sub\" id=\"zapSt\">Checking…</div><label>New zap_key (from ZapUPI dashboard)</label><input id=\"zapKey\" type=\"password\" autocomplete=\"off\" placeholder=\"Paste key\"><button onclick=\"saveZap()\">SAVE ZAPUPI KEY</button></div>';zapLoad()}\n};\nasync function zapLoad(){try{const g=await api('GET','/admin/gateway/zapupi');$('zapSt').textContent=g.tokenConfigured?('Key is set '+(g.keyHint||'')):'Key is NOT set - deposits will not work'}catch(e){$('zapSt').textContent=e.message}}\nasync function saveZap(){const k=$('zapKey').value.trim();if(!k)return toast('Paste the ZapUPI key',1);try{await api('PUT','/admin/gateway/zapupi',{zapKey:k});$('zapKey').value='';toast('ZapUPI key saved');zapLoad()}catch(e){toast(e.message,1)}}\nfunction wCard(w){const redeem=w.method==='gplay',dest=redeem?w.email:w.upi;return`<div class=\"card\"><div class=\"row\"><div class=\"grow\"><b>${money(w.amount)}</b> · ${esc(w.username)} <span class=\"chip ${w.status==='paid'?'ok':w.status==='pending'?'warn':'bad'}\">${w.status}</span><div class=\"sub\">Method: ${redeem?'Google Play Redeem Code':esc(w.method||'UPI')}</div>${redeem?`<div class=\"sub\">Payout value after 20% commission: ${money(w.payoutAmount||w.amount*.8)}</div>`:''}<div class=\"sub\">${redeem?'Gmail':'UPI'}: <b style=\"color:var(--t)\">${esc(dest||'')}</b> <a href=\"#\" onclick=\"navigator.clipboard.writeText('${esc(dest||'')}');toast('Copied');return false\" style=\"color:var(--g)\">copy</a></div><div class=\"sub\">${fdate(w.at)}${w.note?' · '+esc(w.note):''}</div></div></div>${w.status==='pending'?`<div class=\"row\" style=\"margin-top:10px\"><button class=\"s\" onclick=\"wAct('${w.id}','approve')\">${redeem?'Email redeem code':'✓ I paid — mark paid'}</button><button class=\"s d\" onclick=\"wAct('${w.id}','reject')\">Reject & refund</button></div>`:''}</div>`}\nasync function depAct(id,action){let note='';if(action==='approve'){if(!confirm('Did you check this UTR and amount in your UPI/bank app? Coins will be added now.'))return}else{note=prompt('Reason for rejecting (shown to the player):','')||''}\n  try{await api('POST','/admin/deposits/'+id+'/manual',{action,note});toast(action==='approve'?'Coins added':'Rejected');go(cur)}catch(e){toast(e.message,1)}}\nasync function wAct(id,action){const note=action==='reject'?prompt('Reason for rejecting (shown to you in logs):','')||'':'';let redeemCode='';if(action==='approve'){const rows=await api('GET','/admin/withdrawals?status=pending');const w=rows.find(x=>x.id===id);if(w?.method==='gplay'){redeemCode=prompt('Enter Google Play redeem code to email to '+w.email+':','')||'';if(!redeemCode)return}else if(!confirm('Confirm you already sent the money by UPI?'))return}\n  try{await api('POST','/admin/withdrawals/'+id,{action,note,redeemCode});toast(action==='approve'?'Marked paid / code emailed':'Rejected, coins refunded');go(cur)}catch(e){toast(e.message,1)}}\nasync function usersList(){const q=$('uq').value;$('ul').innerHTML='<div class=\"spin\"></div>';try{const u=await api('GET','/admin/users?q='+encodeURIComponent(q));\n  $('ul').innerHTML=u.map(x=>`<div class=\"card\"><div class=\"row\"><div class=\"grow\"><b>${esc(x.username)}</b> ${x.blocked?'<span class=\"chip bad\">blocked</span>':''}<div class=\"sub\">Name: ${esc(x.name||'-')}</div><div class=\"sub\">Mobile: ${esc(x.mobile||'-')} · Email: ${esc(x.email||'-')}</div><div class=\"sub\">UID: ${esc(x.uid)}</div><div class=\"sub\">Deposited ${money(x.deposited)} · Winning ${money(x.winning)} · ${x.totalMatches||0} matches · Kills ${x.totalKills||0}</div></div><button class=\"s o\" onclick=\"userModal('${x.uid}')\">Full details</button></div></div>`).join('')||'<div class=\"card sub\">No users found.</div>'}catch(e){toast(e.message,1)}}\nasync function userModal(uid){const d=await api('GET','/admin/user/'+uid);const u=d.user;\n  modal(`<h2>${esc(u.username)} ${u.blocked?'<span class=\"chip bad\">blocked</span>':''}</h2><div class=\"sub\">${esc(u.firstName||'')} ${esc(u.lastName||'')} · ${esc(u.mobile||'')} · ${esc(u.email||'')}</div>\n  <div class=\"grid\" style=\"margin:12px 0\">${[['Deposited',money(u.deposited)],['Winning',money(u.winning)],['Matches',u.totalMatches||0],['Kills',u.totalKills||0],['Won',money(u.totalWinnings)],['Withdrawn',money(u.totalWithdrawn)]].map(([a,b])=>`<div class=\"card stat\" style=\"margin:0\"><b>${b}</b><span>${a}</span></div>`).join('')}</div>\n  <label>Adjust wallet (use − to remove)</label><div class=\"row\"><input id=\"adA\" type=\"number\" placeholder=\"Amount\" class=\"grow\"><select id=\"adW\" style=\"width:130px\"><option value=\"deposited\">Deposited</option><option value=\"winning\">Winning</option></select></div><input id=\"adR\" placeholder=\"Reason (required)\" style=\"margin-top:8px\">\n  <button onclick=\"adjust('${uid}')\">APPLY</button><button class=\"${u.blocked?'p':'d'}\" onclick=\"blockUser('${uid}',${!u.blocked})\">${u.blocked?'UNBLOCK USER':'BLOCK USER'}</button>\n  <h2 style=\"margin-top:18px\">Recent transactions</h2>`+(d.transactions.map(t=>`<div class=\"row\" style=\"padding:7px 0;border-bottom:1px solid var(--l)\"><div class=\"grow\"><div class=\"ell\">${esc(t.note)}</div><div class=\"sub\">${fdate(t.at)}</div></div><b style=\"color:${t.type==='credit'?'var(--g)':'var(--r)'}\">${t.type==='credit'?'+':'-'}${money(t.amount)}</b></div>`).join('')||'<div class=\"sub\">None</div>')+'<button class=\"o\" onclick=\"close_()\">Close</button>')}\nasync function adjust(uid){try{await api('POST','/admin/adjust',{uid,amount:+$('adA').value,wallet:$('adW').value,reason:$('adR').value});toast('Wallet updated');userModal(uid)}catch(e){toast(e.message,1)}}\nasync function blockUser(uid,b){try{await api('POST','/admin/user/'+uid+'/block',{blocked:b});toast(b?'User blocked':'User unblocked');userModal(uid)}catch(e){toast(e.message,1)}}\nfunction roleChanged(){document.querySelectorAll('.staff-assign').forEach(e=>e.style.display=$('ar').value==='staff'?'':'none')}\nasync function setAdmin(a,name){const username=name||$('an').value;const role=$('ar')?.value||'staff';const gameIds=Array.from(document.querySelectorAll('[data-admin-game]:checked')).map(e=>e.value);if(a&&role==='staff'&&!gameIds.length)return toast('Assign at least one game to Staff',1);try{await api('POST','/admin/admins',{username,admin:a,role,gameIds});toast(a?'Admin / Staff added':'Admin removed');go('admins')}catch(e){toast(e.message,1)}}\nfunction manageAdminGames(uid){const x=(window._admins||[]).find(a=>a.uid===uid);const gs=window._adminGames||[];if(!x)return;modal(`<h2>Games for ${esc(x.username)}</h2>`+gs.map(g=>`<label style=\"display:flex;align-items:center;color:var(--t)\"><input type=\"checkbox\" data-manage-game value=\"${esc(g.id)}\" ${(x.gameIds||[]).includes(g.id)?'checked':''}>${esc(g.name)}</label>`).join('')+`<button onclick=\"saveAdminGames('${esc(uid)}')\">SAVE GAMES</button><button class=\"o\" onclick=\"close_()\">Cancel</button>`)}\nasync function saveAdminGames(uid){const gameIds=Array.from(document.querySelectorAll('[data-manage-game]:checked')).map(e=>e.value);try{await api('PUT','/admin/admins/'+uid+'/games',{gameIds});toast('Staff game access saved');close_();go('admins')}catch(e){toast(e.message,1)}}\nasync function setRole(uid,role){try{await api('POST','/admin/admins/'+uid+'/role',{role});toast('Role updated');go('admins')}catch(e){toast(e.message,1)}}\nasync function saveCfg(){const b={};document.querySelectorAll('[data-c]').forEach(e=>b[e.dataset.c]=e.value);try{await api('PUT','/admin/config',b);const saved=await read('appConfig');const missing=Object.keys(b).filter(k=>String(saved[k]??'')!==String(b[k]??''));if(missing.length)throw Error('Settings were not persisted: '+missing.join(', '));toast('Settings saved and verified')}catch(e){toast(e.message,1)}}\n</script></body></html>\n","/upload.html":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>SURVIVOR SCREEN Image Upload</title>\n<style>\n:root{--bg:#070504;--card:#14100D;--line:#3A2A1C;--g:#FFC21A;--p:#E51B35;--t:#F7F2EA;--m:#A89C8C}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--t);font-family:system-ui,sans-serif;padding:18px;max-width:520px;margin:auto}\nh1{font-size:20px;letter-spacing:3px;margin:8px 0 18px}\n.c{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:16px;margin-bottom:14px}\nlabel{display:block;color:var(--m);font-size:12px;margin:12px 0 6px}\ninput,select{width:100%;padding:13px;border-radius:12px;border:1px solid var(--line);background:#0F0F1C;color:var(--t);font-size:15px}\nbutton{width:100%;margin-top:16px;padding:15px;border:0;border-radius:14px;background:var(--g);color:#000;font-weight:800;font-size:15px;letter-spacing:.5px;transition:transform .12s}\nbutton:active{transform:scale(.95)}button.alt{background:var(--p);color:#fff}button:disabled{opacity:.4}\nimg{width:100%;border-radius:14px;margin-top:12px;display:block}\n#msg{margin-top:12px;font-size:13px;color:var(--m);word-break:break-all}.ok{color:var(--g)!important}.err{color:#FF5C7A!important}\n</style></head><body>\n<h1>SURVIVOR SCREEN · IMAGE UPLOAD</h1>\n\n<div class=\"c\" id=\"login\">\n  <label>Admin username</label><input id=\"u\" autocapitalize=\"none\">\n  <label>Password</label><input id=\"p\" type=\"password\">\n  <button id=\"bl\">LOGIN</button><div id=\"lm\" class=\"err\"></div>\n</div>\n\n<div class=\"c\" id=\"up\" style=\"display:none\">\n  <label>Where does this image go?</label>\n  <select id=\"col\"><option value=\"games\">Game tile</option><option value=\"topgames\">Top Game (Home)</option><option value=\"matches\">Match banner</option>\n    <option value=\"ads\">Home ad banner</option><option value=\"earn_banners\">Earn banner</option><option value=\"banners\">More-tab banner</option></select>\n  <label>Item</label><select id=\"item\"></select>\n  <label>Image (jpg / png / webp)</label><input id=\"f\" type=\"file\" accept=\"image/jpeg,image/png,image/webp\">\n  <img id=\"pv\" style=\"display:none\">\n  <button id=\"bu\" disabled>UPLOAD</button>\n  <div id=\"msg\"></div>\n  <img id=\"res\" style=\"display:none\">\n</div>\n\n<script src=\"https://www.gstatic.com/firebasejs/10.12.2/firebase-app-compat.js\"></script>\n<script src=\"https://www.gstatic.com/firebasejs/10.12.2/firebase-auth-compat.js\"></script>\n<script>\nconst DB='__FB_DB__';\nfirebase.initializeApp({apiKey:'__FB_API__',authDomain:'__FB_AUTH__',projectId:'__FB_PROJECT__'});\nconst $=id=>document.getElementById(id);let user=null,file=null;\n\n$('bl').onclick=async()=>{\n  $('lm').textContent='';\n  try{\n    const c=await firebase.auth().signInWithEmailAndPassword($('u').value.trim().toLowerCase()+'@arenax.user',$('p').value);\n    user=c.user;$('login').style.display='none';$('up').style.display='block';loadItems();\n  }catch(e){$('lm').textContent='Wrong username or password'}\n};\n\nasync function loadItems(){\n  const col=$('col').value;\n  const d=await (await fetch(DB+'/'+col+'.json')).json()||{};\n  $('item').innerHTML='<option value=\"\">(none - just get a link)</option>'+Object.entries(d).map(([k,v])=>'<option value=\"'+k+'\">'+(v.name||v.title||v.text||k)+'</option>').join('');\n}\n$('col').onchange=loadItems;\n\n// shrink big photos before sending (faster upload, faster load in the app)\nfunction shrink(f){return new Promise(r=>{\n  if(f.size<1.2e6)return r(f);\n  const i=new Image();i.onload=()=>{const s=Math.min(1,1600/Math.max(i.width,i.height));\n    const c=document.createElement('canvas');c.width=i.width*s;c.height=i.height*s;c.getContext('2d').drawImage(i,0,0,c.width,c.height);\n    c.toBlob(b=>r(b),'image/jpeg',.85)};i.src=URL.createObjectURL(f)})}\n\n$('f').onchange=e=>{file=e.target.files[0];$('bu').disabled=!file;\n  if(file){$('pv').src=URL.createObjectURL(file);$('pv').style.display='block'}};\n\n$('bu').onclick=async()=>{\n  const m=$('msg');m.className='';m.textContent='Uploading...';$('bu').disabled=true;$('res').style.display='none';\n  try{\n    const blob=await shrink(file),tok=await user.getIdToken(),t0=performance.now();\n    const q='?collection='+($('item').value?$('col').value:'')+'&id='+encodeURIComponent($('item').value);\n    const r=await fetch('/api/admin/upload'+q,{method:'PUT',headers:{Authorization:'Bearer '+tok,'Content-Type':blob.type||file.type},body:blob});\n    const j=await r.json();if(!r.ok)throw new Error(j.error||'Upload failed');\n    const t1=performance.now();\n    $('res').onload=()=>{m.className='ok';m.textContent='Saved to private Telegram channel. Upload '+Math.round(t1-t0)+' ms, image shown in '+Math.round(performance.now()-t1)+' ms. '+(j.assignedTo?'Linked to '+j.assignedTo:'Link: '+j.url)};\n    $('res').src=j.url;$('res').style.display='block';\n  }catch(e){m.className='err';m.textContent=e.message}\n  $('bu').disabled=false;\n};\n</script></body></html>\n"};
globalThis.__RULES = "{\n  \"rules\": {\n    \"usernames\": {\n      \".read\": true,\n      \"$u\": {\n        \".write\": \"auth != null && !data.exists() && newData.val() === auth.uid\"\n      }\n    },\n    \"users\": {\n      \"$uid\": {\n        \".read\": \"auth != null && auth.uid === $uid\",\n        \".write\": \"auth != null && auth.uid === $uid && !data.exists()\",\n        \".validate\": \"newData.child('deposited').val() === 0 && newData.child('winning').val() === 0 && newData.child('totalWinnings').val() === 0 && newData.child('wins').val() === 0 && newData.child('totalMatches').val() === 0 && newData.child('totalWithdrawn').val() === 0 && newData.child('blocked').val() === false && !newData.hasChild('referralRewarded')\"\n      },\n      \".indexOn\": [\n        \"email\",\n        \"mobile\",\n        \"username\"\n      ]\n    },\n    \"games\": {\n      \".read\": true\n    },\n    \"banners\": {\n      \".read\": true\n    },\n    \"matches\": {\n      \".read\": true,\n      \".indexOn\": [\n        \"gameId\",\n        \"status\"\n      ]\n    },\n    \"matchRooms\": {\n      \"$mid\": {\n        \".read\": \"auth != null && root.child('userMatches').child(auth.uid).child($mid).exists()\"\n      }\n    },\n    \"userMatches\": {\n      \"$uid\": {\n        \".read\": \"auth != null && auth.uid === $uid\"\n      }\n    },\n    \"transactions\": {\n      \"$uid\": {\n        \".indexOn\": [\n          \"at\"\n        ],\n        \".read\": \"auth != null && auth.uid === $uid\"\n      }\n    },\n    \"deposits\": {\n      \".indexOn\": [\n        \"status\",\n        \"createdAt\"\n      ]\n    },\n    \"lb\": {\n      \".read\": true,\n      \"$t\": {\n        \"$k\": {\n          \"$g\": {\n            \".indexOn\": [\n              \"amount\"\n            ]\n          }\n        }\n      }\n    },\n    \"ads\": {\n      \".read\": true\n    },\n    \"announcements\": {\n      \".read\": true\n    },\n    \"feedback\": {\n      \".read\": true\n    },\n    \"appConfig\": {\n      \".read\": true,\n      \".write\": \"auth != null && ((root.child('adminPerms').child(auth.uid).child('owner').val() === true || root.child('admins').child(auth.uid).child('role').val() === 'owner') || root.child('adminPerms').child(auth.uid).child('settings_manage').val() === true)\"\n    },\n    \"recentWithdrawals\": {\n      \".read\": true\n    },\n    \"referrals\": {\n      \"$uid\": {\n        \".read\": \"auth != null && auth.uid === $uid\"\n      }\n    },\n    \"tutorials\": {\n      \".read\": true\n    },\n    \"withdrawals\": {\n      \".indexOn\": [\n        \"status\",\n        \"at\"\n      ]\n    },\n    \"userNotifications\": {\n      \"$uid\": {\n        \".read\": \"auth != null && auth.uid === $uid\",\n        \".indexOn\": [\n          \"at\"\n        ]\n      }\n    },\n    \"fcmTokens\": {\n      \"$uid\": {\n        \".read\": false,\n        \".write\": \"auth != null && auth.uid === $uid\"\n      }\n    },\n    \"publishedUpdates\": {\n      \".read\": \"auth != null\",\n      \".indexOn\": [\n        \"publishedAt\"\n      ],\n      \".write\": \"auth != null && ((root.child('adminPerms').child(auth.uid).child('owner').val() === true || root.child('admins').child(auth.uid).child('role').val() === 'owner') || root.child('adminPerms').child(auth.uid).child('settings_manage').val() === true)\"\n    },\n    \"userUpdateReads\": {\n      \"$uid\": {\n        \".read\": \"auth != null && auth.uid === $uid\",\n        \"$id\": {\n          \".write\": \"auth != null && auth.uid === $uid\",\n          \".validate\": \"newData.val() === true\"\n        }\n      }\n    },\n    \"adminUpdates\": {\n      \".read\": \"auth != null && ((root.child('adminPerms').child(auth.uid).child('owner').val() === true || root.child('admins').child(auth.uid).child('role').val() === 'owner') || root.child('adminPerms').child(auth.uid).child('settings_manage').val() === true)\",\n      \".write\": \"auth != null && ((root.child('adminPerms').child(auth.uid).child('owner').val() === true || root.child('admins').child(auth.uid).child('role').val() === 'owner') || root.child('adminPerms').child(auth.uid).child('settings_manage').val() === true)\"\n    },\n    \"adminPerms\": {\n      \".read\": \"auth != null\",\n      \".write\": \"auth != null && root.child('admins').child(auth.uid).child('role').val() === 'owner'\"\n    },\n    \"admins\": {\n      \"$uid\": {\n        \".read\": \"auth != null && (auth.uid === $uid || (root.child('adminPerms').child(auth.uid).child('owner').val() === true || root.child('admins').child(auth.uid).child('role').val() === 'owner'))\",\n        \".write\": \"auth != null && (root.child('adminPerms').child(auth.uid).child('owner').val() === true || root.child('admins').child(auth.uid).child('role').val() === 'owner')\"\n      }\n    },\n    \"teams\": {\n      \".read\": \"auth != null\",\n      \"$tid\": {\n        \".indexOn\": [\n          \"createdAt\",\n          \"ownerUid\",\n          \"inviteCode\"\n        ],\n        \".write\": \"auth != null && ((root.child('adminPerms').child(auth.uid).child('owner').val() === true || root.child('admins').child(auth.uid).child('role').val() === 'owner') || (!data.exists() && newData.child('ownerUid').val() === auth.uid))\",\n        \".validate\": \"newData.hasChildren(['name', 'ownerUid', 'inviteCode', 'createdAt', 'members']) && newData.child('name').isString() && newData.child('name').val().length >= 3 && newData.child('name').val().length <= 24 && newData.child('ownerUid').isString() && newData.child('inviteCode').isString() && newData.child('members').child(newData.child('ownerUid').val()).exists()\",\n        \"members\": {\n          \"$memberUid\": {\n            \".write\": \"auth != null && (auth.uid === $memberUid || (root.child('adminPerms').child(auth.uid).child('owner').val() === true || root.child('admins').child(auth.uid).child('role').val() === 'owner')) && (auth.uid === $memberUid ? (!data.exists() || newData.exists()) : true)\",\n            \".validate\": \"newData.hasChildren(['name', 'at', 'code']) && newData.child('name').isString() && newData.child('at').isNumber() && newData.child('code').isString()\"\n          }\n        }\n      }\n    },\n    \"teamCodes\": {\n      \"$code\": {\n        \".read\": \"auth != null\",\n        \".write\": \"auth != null && ((!data.exists() && root.child('teams').child(newData.val()).child('ownerUid').val() === auth.uid) || (root.child('adminPerms').child(auth.uid).child('owner').val() === true || root.child('admins').child(auth.uid).child('role').val() === 'owner'))\",\n        \".validate\": \"newData.val() == null || newData.isString()\"\n      }\n    },\n    \"userTeam\": {\n      \"$uid\": {\n        \".read\": \"auth != null && auth.uid === $uid\",\n        \".write\": \"auth != null && auth.uid === $uid && (newData.val() == null || newData.isString())\",\n        \".validate\": \"newData.val() == null || newData.isString()\"\n      }\n    },\n    \"teamMessages\": {\n      \"$tid\": {\n        \".read\": \"auth != null && root.child('teams').child($tid).child('members').child(auth.uid).exists()\",\n        \"$mid\": {\n          \".write\": \"auth != null && root.child('teams').child($tid).child('members').child(auth.uid).exists() && (!data.exists() || data.child('senderUid').val() === auth.uid)\",\n          \".validate\": \"newData.hasChildren(['senderUid', 'senderName', 'text', 'at']) && newData.child('senderUid').val() === auth.uid && newData.child('text').isString() && newData.child('text').val().length > 0 && newData.child('text').val().length <= 1000\"\n        }\n      }\n    },\n    \"coupons\": {\n      \".read\": \"auth != null && ((root.child('adminPerms').child(auth.uid).child('owner').val() === true || root.child('admins').child(auth.uid).child('role').val() === 'owner') || root.child('adminPerms').child(auth.uid).child('settings_manage').val() === true)\",\n      \"$code\": {\n        \".write\": \"auth != null && ((root.child('adminPerms').child(auth.uid).child('owner').val() === true || root.child('admins').child(auth.uid).child('role').val() === 'owner') || root.child('adminPerms').child(auth.uid).child('settings_manage').val() === true)\",\n        \".validate\": \"newData.hasChildren(['code', 'amount', 'limit', 'usedCount', 'expiresAt', 'active', 'createdAt']) && newData.child('code').val() === $code && newData.child('amount').isNumber() && newData.child('amount').val() >= 1 && newData.child('amount').val() <= 10000 && newData.child('limit').isNumber() && newData.child('limit').val() >= 0 && newData.child('usedCount').isNumber() && newData.child('usedCount').val() >= 0 && newData.child('expiresAt').isNumber() && newData.child('active').isBoolean()\"\n      },\n      \".indexOn\": [\n        \"active\",\n        \"expiresAt\",\n        \"createdAt\"\n      ]\n    },\n    \"reports\": {\n      \".read\": \"auth != null && ((root.child('adminPerms').child(auth.uid).child('owner').val() === true || root.child('admins').child(auth.uid).child('role').val() === 'owner') || root.child('adminPerms').child(auth.uid).child('users_view').val() === true)\",\n      \".write\": \"auth != null\"\n    }\n  }\n}\n"
