  PROJECT_ID: globalThis.__S.FIREBASE_PROJECT_ID || '',
  DATABASE_URL: globalThis.__S.FIREBASE_DATABASE_URL || '',
  WEB_API_KEY: globalThis.__S.FIREBASE_WEB_API_KEY || '',
  PORT: Number(process.env.PORT) || 3000,
  PUBLIC_URL: (globalThis.__S.PUBLIC_URL || '').replace(/\/$/, ''),

  // Private Telegram channel used as image storage. Bot must be ADMIN of the channel (post permission).
