  TELEGRAM_BOT_TOKEN: globalThis.__S.TELEGRAM_BOT_TOKEN || '',
  TELEGRAM_CHANNEL_ID: globalThis.__S.TELEGRAM_CHANNEL_ID || '',

  // Optional initial signup PIN; set privately in the hosting provider's environment variables.
  ADMIN_DEFAULT_PIN: globalThis.__S.ADMIN_SIGNUP_PIN || '',

  MIN_DEPOSIT: 10,
  MAX_DEPOSIT: 50000,
