    const cmp = (a, b) => { const x = parts(a), y = parts(b); for (let i = 0; i < Math.max(x.length, y.length); i++) { const d = (x[i] || 0) - (y[i] || 0); if (d) return d < 0 ? -1 : 1; } return 0; };
    const all = Object.values((await db.ref('publishedUpdates').get()).val() || {}).filter((u) => u && u.version);
    all.sort((a, b) => cmp(b.latestVersion || b.version, a.latestVersion || a.version) || (b.publishedAt || 0) - (a.publishedAt || 0));
    const u = all[0];
    if (!u) return res.json({});
